 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find rectangular zero canvases and the colored tile seed associated with each.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            # maximal contiguous zero component (orthogonal); canvas areas are rectangles
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            # Only use large rectangular zero regions as canvases.
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if len(cells)!=(r1-r0+1)*(c1-c0+1) or len(cells)<8:
                continue
            # colored seed pattern lies within this canvas; take its connected component(s)
            colored=[]
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if grid[y][x] not in (0,8): colored.append((y,x))
            # The input canvas contains seed markings in its cells; identify their bbox.
            if not colored: continue
            tr0=min(y for y,x in colored); tr1=max(y for y,x in colored)
            tc0=min(x for y,x in colored); tc1=max(x for y,x in colored)
            th,tw=tr1-tr0+1,tc1-tc0+1
            tile=[[grid[tr0+i][tc0+j] for j in range(tw)] for i in range(th)]
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    out[y][x]=tile[(y-tr0)%th][(x-tc0)%tw]
    return out
